/**
 * 《适情雅趣》残局数据集。
 * 数据来源：东萍象棋网 dpxq.com 公开的 DhtmlXQ 棋谱（局面 binit + 着法 movelist）。
 * 经项目引擎逐局校验：setup 结构/局面合法，solution 每步合法且红方先行。
 * 坐标：col 0..8（红方视角左->右），row 0..9，row0=红方底线；大写红小写黑。
 * 仅收录校验通过的局，按原版局号 order 升序；校验未过者未收录。
 */
import type { Move } from '../engine/types';

export interface AncientPuzzle {
  order: number;        // 原版局号 1..N
  title: string;        // 局名
  setup: string;        // 10 行 x 9 格，',' 分格，'/' 分行，大写红小写黑
  solution: Move[];     // 正确解法（红黑交替，红先）
  hintText: string;     // 着法提要
}

function m(
  from: [number, number],
  to: [number, number],
  piece: Move['piece'],
  captured: Move['captured'] = null,
  notation = '',
): Move {
  return {
    from: { col: from[0], row: from[1] },
    to: { col: to[0], row: to[1] },
    piece, captured, notation,
  };
}

